module.exports = function (eleventyConfig) {
  eleventyConfig.addPassthroughCopy({ "app.js": "app.js" });
  eleventyConfig.addPassthroughCopy({ "style.css": "style.css" });
  eleventyConfig.addPassthroughCopy({ "favicon.svg": "favicon.svg" });
  eleventyConfig.addPassthroughCopy({ "cars": "cars" });
  eleventyConfig.addPassthroughCopy({ "bikes": "bikes" });
  eleventyConfig.addPassthroughCopy({ "CNAME": "CNAME" });
  eleventyConfig.addPassthroughCopy({ "robots.txt": "robots.txt" });
  // sitemap is generated by Eleventy from src/sitemap.xml.njk
  eleventyConfig.addPassthroughCopy({ "ads.txt": "ads.txt" });
  eleventyConfig.addPassthroughCopy({ "og-image.png": "og-image.png" });

  // date helper for sitemap
  eleventyConfig.addFilter("date", function (date, format) {
    if (!date) return "";
    // YYYY-MM-DD format
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, "0");
    const d = String(date.getDate()).padStart(2, "0");
    return `${y}-${m}-${d}`;
  });

  return {
    dir: {
      input: "src",
      includes: "_includes",
      output: "_site"
    },
    htmlTemplateEngine: false,
    markdownTemplateEngine: false
  };
};
